from typing import List, Tuple

class Node:
    def __init__(self, id: int, adj: List[int]):
        self.id = id
        self.adj = adj

def f(n: int, adjacency_list: List[Tuple[int, int, List[int]]]) -> int:
    nodes = []
    for u_id, k, v_list in adjacency_list:
        nodes.append(Node(u_id, v_list))

    # calculate maximum distance
    max_distance = 0
    for start_node in nodes:
        visited = [False] * (n + 1)
        distance = 0
        stack = [(start_node, 0)]
        while stack:
            current_node, current_distance = stack.pop()
            if current_distance > distance:
                distance = current_distance
            for adj in current_node.adj:
                if not visited[adj]:
                    visited[adj] = True
                    stack.append((nodes[adj - 1], current_distance + 1))
        if distance > max_distance:
            max_distance = distance
    return max_distance
```

The function `f` reads the adjacency list and constructs a list of `Node` objects. Each `Node` object contains an identifier and a list of adjacent nodes. Then, the function performs a depth-first search (DFS) starting from each node and calculates the maximum distance. The function returns the maximum distance found.

The complexity of the function is O(n^2), where n is the number of nodes in the graph. This is because the function performs a DFS starting from each node, and in the worst case, the DFS will visit all nodes and edges in the graph.

